{"content": "#!/usr/bin/env python3
"""sft_blend_v1 抽样人工检查:10 条随机样本的结构完整性与内容预览。"""
import json
import random

rng = random.Random(123)
rows = [json.loads(l) for l in open("/home/hshen/qwen3_pt/data/sft_blend_v1.jsonl")]
print("total:", len(rows))

VALID = {"system", "user", "assistant", "tool"}
problems = []
for i, r in enumerate(rows):
    ms = r["messages"]
    if not ms or any(m.get("role") not in VALID for m in ms):
        problems.append((i, r["id"], "bad roles"))
    if not any(m["role"] == "assistant" and isinstance(m.get("content"), str) and m["content"].strip() for m in ms):
        problems.append((i, r["id"], "no assistant content"))
    for m in ms:
        c = m.get("content")
        if m["role"] in ("system", "user") and not (isinstance(c, str) and c.strip()):
            problems.append((i, r["id"], f"empty {m['role']} content"))
            break
print("problems:", problems[:20] if problems else "NONE")

for i in rng.sample(range(len(rows)), 10):
    r = rows[i]
    print("=" * 70)
    print(f"[{i}] id={r['id']} source={r['source']} category={r['category']} meta_keys={list(r.get('meta', {}))}")
    for m in r["messages"][:6]:
        c = m.get("content")
        prev = (c[:120].replace("\n", " ") + "...") if isinstance(c, str) and len(c) > 120 else c
        extra = []
        if m.get("reasoning_content"):
            extra.append(f"reasoning={len(m['reasoning_content'])}ch")
        if m.get("tool_calls"):
            extra.append(f"tool_calls={len(m['tool_calls'])}")
        print(f"  {m['role']}: {prev!r} {' '.join(extra)}")
    if len(r["messages"]) > 6:
        print(f"  ... ({len(r['messages'])} messages total)")
", "path": "/tmp/check_v1.py"}

